import json, os
G = os.environ['G']; B = 'research/27-breakdown/batch9'
os.makedirs(B + '/tools', exist_ok=True)
c = json.load(open(G + '/curated-batch9.json'))
L = ['# Девятая партия: +138 дел, всего 3357 (20.11)', '',
'Владелец 20.11: «1, и добавляем ещё новые дела в базу». Партия о частых делах, которых не хватало: стирка по видам вещей, разморозка и простая готовка, пылесос и пыль, мелкие покупки, врачи и анализы, таблетки, квитанции и оплата, банк и связь, Госуслуги и МФЦ, работа и учёба, питомцы, дети, переработка.', '',
'## Как собрано', '',
'1. Около 300 кандидатов, отфильтрованных по базе с пониманием (дословно, уточнения времени и предмета, формы глагола, синонимы предметов, опечатки), затем подмена глагола и общие основы слов. 58 оказались старыми делами другими словами и стали их синонимами ещё до гоблина.',
'2. Планы от goblin.tools (острота 1). Форму шагов исправляет `tools/cur0.py`.',
'3. Смысл исправлен вручную (`tools/cur1.py`, `tools/cur2.py`): «Сделать помидорку» гоблин понял как нарезку помидора (это таймер на 25 минут), «Разобрать тумбочку», «Разобрать полку» и «Разобрать подвал» как разборку отвёрткой и снос, «Обновить приложение банка» и «Доделать курс» от лица разработчика и автора курса, «Проводить на поезд» как поездку самому, «Внести правки научника» не понял, кто такой научник, «Сменить тариф» искал в настройках телефона, «Начать писать диплом» расписал до защиты. Мелкие покупки на 10 шагов сокращены до пяти. Автозамена повелительной формы дала «Делить перерывы» из «Делайте перерывы»: исправлено, и все замены прочитаны.',
'4. Четыре дела написаны вручную взамен неточных синонимов старой базы, которые сняты: «Купить куртку» вела в пальто, «Купить носки» в нижнее бельё, «Подготовиться к встрече» в созвон с камерой, «Отпарить одежду» в отпаривание платья.',
'5. Дубли, которые фильтр не ловит (другие слова того же дела), нашёл проверочный набор и сравнение основ слов уже после гоблина: «Поменять шины» = «Поменять резину», «Сменить тариф на телефоне» = «Сменить тариф», «Собрать заказ из Икеи» = «Собрать мебель», «Внести правки научника» = «Внести правки научрука», «Заменить счётчик воды» = «Поменять счётчики воды», «Поработать 25 минут» = «Сделать помидорку» и ещё 18. Все 24 слиты в синонимы старых дел.',
'6. Минуты оценивает `lib/ai/agents/step-time.ts`, сверху потолок для шагов без ожидания (`tools/mfix.py`) и ручная правка выбросов (`tools/mpatch.py`).', '',
'Проверки: `pnpm check` 845/845, проверочный набор 276 фраз (249 с ожидаемым делом) без единого чужого плана, каждое дело и каждый синоним базы ведут к своему плану, опечатки в названиях и синонимах новых дел узнаются в 98,1 % случаев, ни одна не уходит в чужое дело.', '',
'## Новые дела', '']
for t, v in c['plans'].items():
    L.append(f'**{t}**' + (f'. Синонимы: {", ".join(v["synonyms"])}' if v['synonyms'] else ''))
    L += [f'{i + 1}. {s}' for i, s in enumerate(v['steps'])]
    L.append('')
L += ['## Стали синонимами старых дел', '']
L += [f'- {k} → {v}' for k, v in sorted(c['skip'].items())]
open(B + '/README.md', 'w').write('\n'.join(L) + '\n')
p = 'CLAUDE.md'; s = open(p).read()
i = s.index('  **Восьмая партия'); j = s.index('\n  **', i + 5)
add = '\n  **Девятая партия — +138 дел, всего 3357 (20.11, владелец: «добавляем ещё новые дела в базу»):** стирка по видам вещей, готовка, мелкие покупки,\n  врачи и анализы, квитанции, банк и связь, работа и учёба, питомцы. 82 кандидата оказались старыми делами другими словами и стали синонимами\n  («Поменять шины» = «Поменять резину»): такие дубли ловит только проверочный набор и сравнение основ, не фильтр опечаток. Гоблин понял не так:\n  «Сделать помидорку» — нарезка помидора, «Разобрать полку» — разборка отвёрткой. Отчёт — `research/27-breakdown/batch9/`.'
if 'Девятая партия' not in s: s = s[:j] + add + s[j:]
open(p, 'w').write(s)
